  // 艾宾浩斯间隔（分钟）：0=立即, 5min, 30min, 12h, 1d, 2d, 4d, 7d, 15d, 30d
  const INTERVALS = [0, 5, 30, 720, 1440, 2880, 5760, 10080, 21600, 43200];

  const LS = {
    progress: "gxzsb.wb.prog",
    today: "gxzsb.wb.today",
    dailyGoal: "gxzsb.wb.goal",
    learnOrder: "gxzsb.wb.order"
  };

  function load(k, fb) {
    try { return JSON.parse(localStorage.getItem(k)) !== null ? JSON.parse(localStorage.getItem(k)) : fb; }
    catch (e) { return fb; }
  }
  function save(k, v) {
    try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {}
  }

  function getProgress() { return load(LS.progress, {}); }
  function setProgress(p) { save(LS.progress, p); }

  function getLearnOrder() {
    let order = load(LS.learnOrder, null);
    if (!order || order.length !== WORDS.length) {
      order = WORDS.map(function(_, i) { return i; });
      for (var i = order.length - 1; i > 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        var tmp = order[i]; order[i] = order[j]; order[j] = tmp;
      }
      save(LS.learnOrder, order);
    }
    return order;
  }

  function getDailyGoal() { return load(LS.dailyGoal, 20); }
  function setDailyGoal(n) { save(LS.dailyGoal, n); }

  function getTodayKey() {
    var d = new Date();
    return d.getFullYear() + "-" + (d.getMonth()+1) + "-" + d.getDate();
  }
  function getTodayLearned() {
    var t = load(LS.today, {});
    if (t.date !== getTodayKey()) return { date: getTodayKey(), learned: 0, reviewed: 0 };
    return t;
  }
  function incToday(kind) {
    var t = getTodayLearned();
    t[kind] = (t[kind] || 0) + 1;
    t.date = getTodayKey();
    save(LS.today, t);
  }

  function getNewWords(count) {
    var prog = getProgress();
    var order = getLearnOrder();
    var result = [];
    for (var i = 0; i < order.length; i++) {
      var w = WORDS[order[i]];
      if (!prog[w.id]) result.push(w);
      if (result.length >= count) break;
    }
    return result;
  }

  function getDueReview() {
    var prog = getProgress();
    var now = Date.now();
    var result = [];
    for (var id in prog) {
      var p = prog[id];
      if (p.box >= 3) continue;
      if (p.next <= now) {
        var w = null;
        for (var i = 0; i < WORDS.length; i++) {
          if (WORDS[i].id === id) { w = WORDS[i]; break; }
        }
        if (w) { var c = {}; for (var k in w) c[k] = w[k]; c._p = p; result.push(c); }
      }
    }
    return result;
  }

  function markWord(id, know) {
    var prog = getProgress();
    var now = Date.now();
    if (!prog[id]) prog[id] = { stage: 0, next: 0, box: 1 };
    var p = prog[id];
    if (know) {
      p.stage = Math.min(p.stage + 1, INTERVALS.length - 1);
      p.box = p.stage >= 8 ? 3 : (p.stage >= 3 ? 2 : 1);
    } else {
      p.stage = Math.max(0, p.stage - 2);
      p.box = 1;
    }
    p.next = now + INTERVALS[p.stage] * 60 * 1000;
    p.last = now;
    setProgress(prog);
    incToday(know ? "reviewed" : "learned");
  }

  function getStats() {
    var prog = getProgress();
    var learning = 0, reviewing = 0, mastered = 0, unlearned = WORDS.length;
    for (var id in prog) {
      unlearned--;
      var b = prog[id].box;
      if (b === 3) mastered++;
      else if (b === 2) reviewing++;
      else learning++;
    }
    var today = getTodayLearned();
  
  // 生成看词选义题：给出单词，4个释义选项
  function genMeaningQuiz(word) {
    var correct = word.m;
    var options = [correct];
    var pool = WORDS.filter(function(w) { return w.m !== correct && w.m.length > 0; });
    // 随机选3个干扰项
    var shuffled = pool.slice().sort(function() { return Math.random() - 0.5; });
    for (var i = 0; i < shuffled.length && options.length < 4; i++) {
      if (options.indexOf(shuffled[i].m) < 0) {
        options.push(shuffled[i].m);
      }
    }
    // 打乱选项顺序
    options = options.sort(function() { return Math.random() - 0.5; });
    return {
      type: 'meaning',
      word: word,
      question: word.w,
      phonetic: word.ph,
      options: options,
      answer: correct
    };
  }

  // 生成看义选词题：给出释义，4个单词选项
  function genWordQuiz(word) {
    var correct = word.w;
    var options = [correct];
    var pool = WORDS.filter(function(w) { return w.w !== correct; });
    var shuffled = pool.slice().sort(function() { return Math.random() - 0.5; });
    for (var i = 0; i < shuffled.length && options.length < 4; i++) {
      if (options.indexOf(shuffled[i].w) < 0) {
        options.push(shuffled[i].w);
      }
    }
    options = options.sort(function() { return Math.random() - 0.5; });
    return {
      type: 'word',
      word: word,
      question: word.m,
      phonetic: word.ph,
      options: options,
      answer: correct
    };
  }

  // 生成拼写题：给出释义和音标，用户输入单词
  function genSpellQuiz(word) {
    return {
      type: 'spell',
      word: word,
      question: word.m,
      phonetic: word.ph,
      answer: word.w,
      // 给出首字母提示
      hint: word.w.charAt(0) + '_'.repeat(Math.max(0, word.w.length - 1))
    };
  }

  // 从词表生成混合练习（三种题型随机）
  function genMixedQuiz(words) {
    var quizzes = [];
    for (var i = 0; i < words.length; i++) {
      var r = Math.random();
      if (r < 0.4) quizzes.push(genMeaningQuiz(words[i]));
      else if (r < 0.75) quizzes.push(genWordQuiz(words[i]));
      else quizzes.push(genSpellQuiz(words[i]));
    }
    return quizzes;
  }

  return { total: WORDS.length, unlearned: unlearned, learning: learning, reviewing: reviewing, mastered: mastered, today: today };
  }

  // 按字母搜索
  function searchWords(query) {
    var q = query.toLowerCase().trim();
    if (!q) return [];
    return WORDS.filter(function(w) {
      return w.w.toLowerCase().indexOf(q) >= 0 || w.m.indexOf(q) >= 0;
    }).slice(0, 50);
  }


